/**
* 把 agent-ui 内部 locale 映射为腾讯文档 `/i18n/user/multi-language` 接口的
* `userLanguage` 取值。
*
* agent-ui 当前只支持 `'en'` / `'zh-cn'` 两种内部 locale（繁体 `zh-hk` 会被 i18n
* 框架归一化为 `zh-cn`）。这里仍显式保留 `zh-hk → zh-HK` 分支，便于将来 i18n
* 扩展繁体后无需再动本处。
*/
function toDocUserLanguage(locale) {
	const normalized = (locale || "").toLowerCase();
	if (normalized === "zh-hk") return "zh-HK";
	if (normalized === "en" || normalized.startsWith("en")) return "en-US";
	return "zh-CN";
}
